insert into public.portal_hazards(id,type,severity,severity_label,title,summary,area,country,zone_lat,zone_lon,zone_km,erp_index,site_names,facts,sources,published_at,updated_label) values
('TH-FL-2610-12','flood','em','Emergency','อุทกภัยภาคกลาง–ตะวันออก กระทบ 2.46 ล้านคน ใน 20 จังหวัดและกรุงเทพฯ','ฝนตกหนักต่อเนื่องและน้ำเหนือไหลลงลุ่มน้ำภาคกลาง ระดับน้ำส่วนใหญ่ทรงตัวหรือลดลง แต่ลุ่มน้ำบางปะกงคาดว่าต้องใช้เวลาระบายน้ำ 38 วัน (ถึงกลาง พ.ย.)','ปทุมธานี · ปราจีนบุรี · นครนายก · ฉะเชิงเทรา · อยุธยา · กรุงเทพฯ','Thailand',14.05,100.95,135,12,ARRAY['Thai Containers Group - Pathumthani','Thai Containers Group - Navanakorn','Thai Containers Group - Prachinburi','Thai Cane Paper - Prachinburi','Teamplas','Thai Containers Group - Samutprakan','Orient Container - Narkorn Pathom','Prepack Thailand - Samut Songkhram']::text[],'[["ผู้ได้รับผลกระทบ", "2,458,895 คน", "908,595 ครัวเรือน · 100 อำเภอ"], ["ปทุมธานี", "248,818 ครัวเรือน", "ระดับน้ำทรงตัว"], ["เสียชีวิต (ตั้งแต่ 16 ก.ย.)", "60 ราย", "กระทรวงมหาดไทย ณ 7 ต.ค."], ["สถานประกอบการกระทบ", "1,315 แห่ง", "40 จังหวัด (ก.อุตสาหกรรม)"]]'::jsonb,'[{"name": "Nation Thailand", "url": "https://www.nationthailand.com/news/general/40072167", "date": "12 ต.ค. 2026"}, {"name": "Nation Thailand", "url": "https://www.nationthailand.com/news/general/40072128", "date": "11 ต.ค. 2026"}, {"name": "Thailand Explained", "url": "https://thailandexplained.substack.com/p/weekly-insight-42-1-7-october-2026", "date": "7 ต.ค. 2026"}]'::jsonb,'2026-10-12T06:00:00+07:00','12 ต.ค. 2026 · 06:00'),
('TH-RN-2610-10','rain','wa','Warning','เตือนฝนตกหนัก 10–13 ต.ค. เขื่อนหลักใกล้เต็ม เร่งระบายน้ำลุ่มแม่กลอง–ป่าสัก','JICC เตือนฝนหนักภาคกลาง ตะวันตก และใต้ เขื่อนป่าสักชลสิทธิ์เต็มและระบายน้ำสู่เขื่อนพระราม 6 เขื่อนวชิราลงกรณ 98% เขื่อนศรีนครินทร์ 90% เขื่อนแก่งกระจานเต็ม','กาญจนบุรี · ราชบุรี · สมุทรสาคร · สระบุรี · เพชรบุรี','Thailand',14.05,99.95,150,12,ARRAY['Siam Kraft Industry - Kanchanab','Thai Cane Paper - Kanchanaburi','Thai Paper - Pulp Production-Wangsala','Siam Kraft Industry - Ratchaburi','Thai Containers Group - Ratchaburi','Thai Paper - Pulp Production-Banpong','Orient Container - Samutsakhon','Siam Cement - Kaeng Khoi Plant','Siam Cement - Ta Luang Plant','Saraburirat - SBR']::text[],'[["เขื่อนป่าสักชลสิทธิ์", "เต็มความจุ", "ระบายสู่เขื่อนพระราม 6"], ["เขื่อนวชิราลงกรณ", "98%", "ระบายมากกว่าน้ำเข้า"], ["เขื่อนเจ้าพระยา", "2,500 ลบ.ม./วิ", "ระดับน้ำ 16.88 ม."], ["ช่วงเตือนภัย", "10–13 ต.ค.", "ฝนปานกลางถึงหนัก"]]'::jsonb,'[{"name": "Khaosod English", "url": "https://www.khaosodenglish.com/featured/2026/10/06/heavy-rain-forecast-across-thailand-as-authorities-monitor-flood-risks/amp/", "date": "6 ต.ค. 2026"}]'::jsonb,'2026-10-06T12:00:00+07:00','6 ต.ค. 2026 · เตือนช่วง 10–13 ต.ค.'),
('VN-FL-2610-09','flood','wa','Warning','น้ำท่วมฉับพลันและดินถล่มเวียดนามตอนกลาง เว้ฝนสะสมกว่า 800 มม. ใน 3 วัน','ดานังน้ำท่วมสูงกว่า 1 เมตรในบางพื้นที่ ถนนบนภูเขาถูกดินถล่มปิด รัฐบาลส่งทหารราว 130 นายและรถสะเทินน้ำสะเทินบกช่วยอพยพ เตือนฝนตกต่อถึงเช้าวันอาทิตย์','เว้ · ดานัง · กวางนาม','Vietnam',16.25,107.9,170,12,ARRAY['Danang Cement','Mien Trung Cement','Song Gianh Cement']::text[],'[["ฝนสะสม 3 วัน (เว้)", "> 800 มม.", "ที่ราบชายฝั่งและเนินเขาตอนใต้"], ["ระดับน้ำในดานัง", "> 1 ม.", "บางพื้นที่"], ["กำลังพลช่วยเหลือ", "~130 นาย", "ในดานัง"], ["สูญหาย", "1 ราย", "เรือล่มในแม่น้ำ Truong Giang"]]'::jsonb,'[{"name": "Mongabay / AP", "url": "https://news.mongabay.com/short-article/2026/10/vietnam-mobilizes-troops-after-heavy-rains-trigger-flash-floods-and-raise-risks-of-landslides/", "date": "9 ต.ค. 2026"}, {"name": "Washington Post", "url": "https://www.washingtonpost.com/world/2026/10/09/vietnam-floods-hue-danang-climate-change/2cb3d510-c3bf-11f1-8170-681419af1cc9_story.html", "date": "9 ต.ค. 2026"}, {"name": "Dan Tri International", "url": "https://dtinews.dantri.com.vn/vietnam-today/flood-warning-issued-for-rivers-in-central-vietnam-20261009120516595.htm", "date": "9 ต.ค. 2026"}]'::jsonb,'2026-10-09T12:00:00+07:00','9 ต.ค. 2026'),
('VN-TD-2610-09','tide','wt','Watch','น้ำทะเลหนุนสูงและฝนหนัก นครโฮจิมินห์อาจเกินระดับเตือนภัย 3','น้ำขึ้นสูงสุดที่ Vung Tau 4.0–4.05 ม. คาดว่าน้ำในนครโฮจิมินห์สูงสุดช่วง 10–12 ต.ค. แม่น้ำดองไนที่สถานี Ta Lai อยู่ระดับเตือนภัย 2 เสี่ยงน้ำท่วมพื้นที่ต่ำและตลิ่งพัง','นครโฮจิมินห์ · ดองไน · บิ่ญเซือง','Vietnam',10.85,106.75,75,12,ARRAY['Buu Long','Bien Hoa Packaging - Dong Nai','Bien Hoa Packaging - Ho Chi Minh','Vina Corrugated Packaging - Ho Chi Minh','Vina Corrugated Packaging - Binh Duong','Tin Thanh Packing','Vietnam Construction Materials','LSP - Vietnam']::text[],'[["น้ำขึ้นสูงสุด Vung Tau", "4.0–4.05 ม.", "9 ต.ค."], ["แม่น้ำดองไน (Ta Lai)", "112.5 ม.", "ระดับเตือนภัย 2"], ["ช่วงน้ำสูงสุด", "10–12 ต.ค.", "อาจเกินระดับ 3"]]'::jsonb,'[{"name": "SGGP English", "url": "https://en.sggp.org.vn/heavy-rain-high-tides-may-push-ho-chi-minh-city-water-levels-above-level-3-post130190.html", "date": "9 ต.ค. 2026"}]'::jsonb,'2026-10-09T05:00:00+07:00','9 ต.ค. 2026 · เฝ้าระวัง 10–12 ต.ค.'),
('ID-HZ-2610-08','haze','wt','Watch','ไฟป่าอินโดนีเซีย 1,176 จุด หมอกควันข้ามพรมแดน คุณภาพอากาศถึงระดับอันตราย','จุดความร้อนเพิ่มขึ้นมากในกาลิมันตันกลางและสุมาตราใต้ ทัศนวิสัยที่ปาลังการายาเหลือ 150 ม. มีเที่ยวบินยกเลิกและล่าช้า ไม่มี Site ของ SCG ในพื้นที่ hotspot โดยตรง ให้ติดตามผลต่อการขนส่งและ supply chain','กาลิมันตันกลาง · สุมาตราใต้ · จัมบี','Indonesia',-1.8,111.5,420,17,'{}'::text[],'[["จุดความร้อนทั้งประเทศ", "1,176 จุด", "ความเชื่อมั่นสูง"], ["กาลิมันตันกลาง", "225 จุด", "เพิ่มจาก 182"], ["สุมาตราใต้", "224 จุด", "เพิ่มจาก 71"], ["ทัศนวิสัยปาลังการายา", "150 ม.", "เที่ยวบินได้รับผลกระทบ"]]'::jsonb,'[{"name": "Bernama", "url": "https://bernama.com/en/news.php?id=2617055", "date": "8 ต.ค. 2026"}, {"name": "New Straits Times", "url": "https://www.nst.com.my/amp/world/region/2026/10/1549997/indonesia-records-1201-hotspots-haze-persists-malaysia", "date": "ต.ค. 2026"}]'::jsonb,'2026-10-08T21:00:00+07:00','8 ต.ค. 2026'),
('PH-EQ-2610-08','quake','ad','Advisory','แผ่นดินไหวขนาด 5.6 นอกชายฝั่งดาเวาออคซิเดนทัล ฟิลิปปินส์','PHIVOLCS ระบุศูนย์กลางห่างเกาะ Balut ราว 28 กม. ลึก 26 กม. รับรู้ได้ถึงระดับ V ที่ Kiamba และ General Santos ไม่คาดว่าจะเกิดความเสียหาย เป็น aftershock ของแผ่นดินไหว M7.8 เมื่อ มิ.ย. 2026','Sarangani · General Santos · Davao','Philippines',5.61,125.26,120,14,ARRAY['Mariwasa','United Pulp and Paper','SCG Inter - Coal hub-Philippines']::text[],'[["ขนาด", "M 5.6", "ลึก 26 กม."], ["ความรุนแรงที่รับรู้", "ระดับ V", "Kiamba, General Santos"], ["ระยะถึง Site ใกล้สุด", "~950 กม.", "Site ในเขตมะนิลา"]]'::jsonb,'[{"name": "Manila Bulletin", "url": "https://mb.com.ph/2026/10/08/56-magnitude-quake-rocks-davao-occidental-phivolcs", "date": "8 ต.ค. 2026"}, {"name": "PhilNews", "url": "https://philnews.ph/2026/10/08/earthquake-5-6-magnitude-quake-hits-davao-occidental-october-8-2026/", "date": "8 ต.ค. 2026"}]'::jsonb,'2026-10-08T08:07:00+08:00','8 ต.ค. 2026')
